package com.franco.desco.adapter.out.sqlserver.resourceprogram;import com.franco.desco.adapter.out.sqlserver.shared.*;import com.franco.desco.application.resourceprogram.*;import com.franco.desco.application.resourceprogram.port.out.ResourceProgramPersistencePort;import com.franco.desco.application.shared.*;import com.franco.desco.application.shared.pagination.PageResult;import com.franco.desco.domain.resourceprogram.ResourceProgramModels;import org.springframework.jdbc.core.simple.SimpleJdbcCall;import org.springframework.stereotype.Component;import java.util.*;
@Component public class ResourceProgramSqlServerAdapter implements ResourceProgramPersistencePort{private final SqlServerPaExecutor e;private final PaPayloadFactory pf;private final SimpleJdbcCall list,get,availability,program,update,assign,returnCall,cancel;public ResourceProgramSqlServerAdapter(SqlServerPaFactory f,SqlServerPaExecutor e,PaPayloadFactory pf){this.e=e;this.pf=pf;list=f.callWithResultSets("logistica","PA_RecursoProgramado_Sel_Listado","items");get=f.callWithResultSets("logistica","PA_RecursoProgramado_Sel_Detalle","header","movements");availability=f.callWithResultSets("logistica","PA_RecursoProgramado_Sel_Disponibilidad","assets","supplies");program=f.call("logistica","PA_RecursoProgramado_Ins_Programar");update=f.call("logistica","PA_RecursoProgramado_Upd_Registro");assign=f.call("logistica","PA_RecursoProgramado_Ins_Asignar");returnCall=f.call("logistica","PA_RecursoProgramado_Ins_Devolucion");cancel=f.call("logistica","PA_RecursoProgramado_Upd_Cancelar");}
 public PersistenceResult<PageResult<ResourceProgramModels.Summary>>list(ResourceProgramCommands.ListResources c,SessionIdentity i,RequestMetadata m){var pg=c.page();var f=pg.filtros();var payload=pf.forQuery(i,m,map("filtros",map("estadoProceso",f==null?null:f.estadoProceso(),"campaniaVentaId",f==null?null:f.campaniaVentaId(),"operativoVentaId",f==null?null:f.operativoVentaId(),"salidaCampoId",f==null?null:f.salidaCampoId()),"paginacion",map("pagina",pg.pagina(),"tamano",pg.tamanio())));var out=e.executeJson(list,payload);return PaAdapterSupport.page(out,rows(out,"items"),pg.pagina(),pg.tamanio(),this::summary,"No se pudieron consultar los recursos programados.");}
 public PersistenceResult<ResourceProgramModels.Detail>get(ResourceProgramCommands.Get c,SessionIdentity i,RequestMetadata m){var out=e.executeJson(get,pf.forQuery(i,m,Map.of("recurso",Map.of("recursoProgramadoId",c.recursoProgramadoId()))));if(!PaAdapterSupport.success(out))return PersistenceResult.error(PaAdapterSupport.message(out,"No se pudo consultar el recurso."));var h=one(out,"header");if(h==null)return PersistenceResult.error("El recurso seleccionado no está disponible.");return PersistenceResult.ok(PaAdapterSupport.message(out,"Recurso consultado correctamente."),new ResourceProgramModels.Detail(SqlValues.longValue(h,"recursoProgramadoId"),SqlValues.longValue(h,"campaniaVentaId"),SqlValues.longValue(h,"operativoVentaId"),SqlValues.longValue(h,"salidaCampoId"),SqlValues.longValue(h,"bienInventarioId"),SqlValues.string(h,"bien"),SqlValues.string(h,"estadoBien"),SqlValues.longValue(h,"suministroId"),SqlValues.string(h,"suministro"),SqlValues.string(h,"unidadMedida"),SqlValues.decimal(h,"cantidadProgramada"),SqlValues.string(h,"observacion"),SqlValues.bool(h,"estado"),SqlValues.string(h,"estadoProceso"),SqlValues.longValue(h,"usuarioProgramacionId"),SqlValues.instant(h,"fechaProgramacion"),SqlValues.longValue(h,"usuarioCancelacionId"),SqlValues.instant(h,"fechaCancelacion"),SqlValues.string(h,"motivoCancelacion"),rows(out,"movements").stream().map(this::movement).toList()));}
 public PersistenceResult<ResourceProgramModels.Availability>availability(SessionIdentity i,RequestMetadata m){var out=e.executeJson(availability,pf.forQuery(i,m,Map.of()));if(!PaAdapterSupport.success(out))return PersistenceResult.error(PaAdapterSupport.message(out,"No se pudo consultar la disponibilidad."));return PersistenceResult.ok(PaAdapterSupport.message(out,"Disponibilidad consultada correctamente."),new ResourceProgramModels.Availability(rows(out,"assets").stream().map(r->new ResourceProgramModels.AvailableAsset(SqlValues.longValue(r,"bienInventarioId"),SqlValues.string(r,"codigoPatrimonial"),SqlValues.string(r,"nombre"),SqlValues.string(r,"estadoBien"),SqlValues.bool(r,"disponible"))).toList(),rows(out,"supplies").stream().map(r->new ResourceProgramModels.AvailableSupply(SqlValues.longValue(r,"suministroId"),SqlValues.string(r,"codigo"),SqlValues.string(r,"nombre"),SqlValues.string(r,"unidadMedida"),SqlValues.decimal(r,"stockDisponible"))).toList()));}
 public PersistenceResult<Long>program(ResourceProgramCommands.Program c,SessionIdentity i,RequestMetadata m){var out=e.executeJson(program,pf.forWrite(i,m,c,Map.of("recurso",map("campaniaVentaId",c.campaniaVentaId(),"operativoVentaId",c.operativoVentaId(),"salidaCampoId",c.salidaCampoId(),"bienInventarioId",c.bienInventarioId(),"suministroId",c.suministroId(),"cantidadProgramada",c.cantidadProgramada(),"observacion",c.observacion()))));return PaAdapterSupport.result(out,SqlValues.longValue(out,"nRecursoProgramadoId"),"No se pudo programar el recurso.");}
 public PersistenceResult<Void>update(ResourceProgramCommands.Update c,SessionIdentity i,RequestMetadata m){return mut(update,i,m,c,map("recursoProgramadoId",c.recursoProgramadoId(),"cantidadProgramada",c.cantidadProgramada(),"observacion",c.observacion()),"No se pudo actualizar el recurso.");}public PersistenceResult<Void>assign(ResourceProgramCommands.Assign c,SessionIdentity i,RequestMetadata m){return mut(assign,i,m,c,map("recursoProgramadoId",c.recursoProgramadoId()),"No se pudo asignar el recurso.");}public PersistenceResult<Void>returnResource(ResourceProgramCommands.ReturnResource c,SessionIdentity i,RequestMetadata m){return mut(returnCall,i,m,c,map("recursoProgramadoId",c.recursoProgramadoId(),"cantidadDevuelta",c.cantidadDevuelta(),"observacion",c.observacion()),"No se pudo registrar la devolución.");}public PersistenceResult<Void>cancel(ResourceProgramCommands.Cancel c,SessionIdentity i,RequestMetadata m){return mut(cancel,i,m,c,map("recursoProgramadoId",c.recursoProgramadoId(),"motivo",c.motivo()),"No se pudo cancelar el recurso.");}
 private PersistenceResult<Void>mut(SimpleJdbcCall call,SessionIdentity i,RequestMetadata m,Object body,Map<String,Object>r,String f){return PaAdapterSupport.result(e.executeJson(call,pf.forWrite(i,m,body,Map.of("recurso",r))),null,f);}private ResourceProgramModels.Summary summary(Map<String,Object>r){return new ResourceProgramModels.Summary(SqlValues.longValue(r,"recursoProgramadoId"),SqlValues.longValue(r,"campaniaVentaId"),SqlValues.longValue(r,"operativoVentaId"),SqlValues.longValue(r,"salidaCampoId"),SqlValues.longValue(r,"bienInventarioId"),SqlValues.string(r,"bien"),SqlValues.longValue(r,"suministroId"),SqlValues.string(r,"suministro"),SqlValues.decimal(r,"cantidadProgramada"),SqlValues.string(r,"estadoProceso"),SqlValues.instant(r,"fechaProgramacion"),SqlValues.string(r,"observacion"),SqlValues.decimal(r,"cantidadEjecutada"),SqlValues.decimal(r,"cantidadDevuelta"));}private ResourceProgramModels.Movement movement(Map<String,Object>r){return new ResourceProgramModels.Movement(SqlValues.longValue(r,"recursoMovimientoId"),SqlValues.string(r,"tipoMovimiento"),SqlValues.decimal(r,"cantidad"),SqlValues.instant(r,"fechaHora"),SqlValues.string(r,"observacion"),SqlValues.string(r,"usuario"));}private List<Map<String,Object>>rows(Map<String,Object>o,String k){return new PaResultSets(o).rows(k);}private Map<String,Object>one(Map<String,Object>o,String k){return new PaResultSets(o).one(k).orElse(null);}private static Map<String,Object>map(Object...v){Map<String,Object>m=new LinkedHashMap<>();for(int n=0;n<v.length;n+=2)if(v[n+1]!=null)m.put((String)v[n],v[n+1]);return m;}}
